+const { useState } = React;
+
+const FormField = ({ label, id, type, required, autocomplete, helperText, value, onChange, error }) => {
+  return (
+    <div className="form-field">
+      <label htmlFor={id}>
+        {label}
+        {required && <span className="required-marker" aria-hidden="true">*</span>}
+      </label>
+      <input
+        id={id}
+        name={id}
+        type={type}
+        required={required}
+        autoComplete={autocomplete}
+        value={value}
+        onChange={onChange}
+        aria-describedby={helperText ? `${id}-helper` : (error ? `${id}-error` : undefined)}
+        aria-invalid={!!error}
+      />
+      {helperText && (
+        <p className="helper-text" id={`${id}-helper`}>
+          {helperText}
+        </p>
+      )}
+      {error && (
+        <p className="error-message" id={`${id}-error`}>
+          Error: {error}
+        </p>
+      )}
+    </div>
+  );
+};
+
+const ContactForm = () => {
+  const [formData, setFormData] = useState({
+    name: '',
+    email: '',
+    phone: ''
+  });
+  const [errors, setErrors] = useState({});
+  const [submitted, setSubmitted] = useState(false);
+
+  const handleChange = (e) => {
+    const { name, value } = e.target;
+    setFormData(prev => ({ ...prev, [name]: value }));
+    // Clear error when user starts typing
+    if (errors[name]) {
+      setErrors(prev => {
+        const newErrors = { ...prev };
+        delete newErrors[name];
+        return newErrors;
+      });
+    }
+  };
+
+  const validate = () => {
+    const newErrors = {};
+    if (!formData.name.trim()) newErrors.name = 'Full name is required';
+    if (!formData.email.trim()) {
+      newErrors.email = 'Email address is required';
+    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
+      newErrors.email = 'Please enter a valid email address';
+    }
+    return newErrors;
+  };
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    const newErrors = validate();
+    if (Object.keys(newErrors).length > 0) {
+      setErrors(newErrors);
+      // Focus the first invalid field
+      const firstErrorKey = Object.keys(newErrors)[0];
+      document.getElementById(firstErrorKey)?.focus();
+    } else {
+      setSubmitted(true);
+      console.log('Form submitted:', formData);
+    }
+  };
+
+  if (submitted) {
+    return (
+      <div className="container" role="status" aria-live="polite">
+        <h1>Thank you!</h1>
+        <p>Your support request has been sent successfully. We'll get back to you soon.</p>
+        <button onClick={() => setSubmitted(false)}>Send another message</button>
+      </div>
+    );
+  }
+
+  return (
+    <div className="container">
+      <header>
+        <h1>Support Request</h1>
+        <p className="subtitle">Fill out the form below and we'll help you get started.</p>
+      </header>
+      <form onSubmit={handleSubmit} noValidate>
+        <FormField
+          label="Full Name"
+          id="name"
+          type="text"
+          required={true}
+          autocomplete="name"
+          value={formData.name}
+          onChange={handleChange}
+          error={errors.name}
+        />
+        <FormField
+          label="Email Address"
+          id="email"
+          type="email"
+          required={true}
+          autocomplete="email"
+          value={formData.email}
+          onChange={handleChange}
+          error={errors.email}
+        />
+        <FormField
+          label="Phone Number (optional)"
+          id="phone"
+          type="tel"
+          required={false}
+          autocomplete="tel"
+          helperText="Expected format: 123-456-7890"
+          value={formData.phone}
+          onChange={handleChange}
+          error={errors.phone}
+        />
+        <button type="submit">Send support request</button>
+      </form>
+    </div>
+  );
+};
